<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$mode=$argv[1] ?? '';
if(!in_array($mode,['seed','purge','status'],true))exit("Usage: php bin/demo.php seed|purge|status\nSamples are visibly fictional. Purge deletes only tagged demo records, including edited demo records.\n");
$root=dirname(__DIR__);$c=require $root.'/config.php';
$db=new PDO($c['dsn'],$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
foreach(['projects','posts','reviews','enquiries'] as $table){$q=$db->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name='demo_key'");$q->execute([$table]);if(!(int)$q->fetchColumn())exit("Database upgrade required. Run php bin/upgrade.php first.\n");}
const DEMO_PREFIX='aes-demo-v1:';
function demoQuery(string $sql,array $params=[]): PDOStatement {global $db;$q=$db->prepare($sql);$q->execute($params);return $q;}
function demoImage(int $kind,int $variation): string {
    global $root;$name=bin2hex(random_bytes(24)).'.jpg';$directory=$root.'/storage/photos';if(!is_dir($directory))mkdir($directory,0700,true);
    $im=imagecreatetruecolor(1200,800);$sky=imagecolorallocate($im,218,235,239);$ink=imagecolorallocate($im,17,51,73);$blue=imagecolorallocate($im,21,78,118);$line=imagecolorallocate($im,136,184,207);$orange=imagecolorallocate($im,248,154,45);$white=imagecolorallocate($im,255,255,255);
    imagefill($im,0,0,$sky);imagefilledellipse($im,1020,160,130,130,$orange);imagefilledrectangle($im,0,650,1200,800,imagecolorallocate($im,159,190,167));
    if($kind===0){imagefilledpolygon($im,[100,420,550,240,1050,420,1050,650,100,650],$white);for($x=200;$x<1000;$x+=150)for($y=400;$y<600;$y+=90){imagefilledrectangle($im,$x,$y,$x+135,$y+75,$blue);imagerectangle($im,$x,$y,$x+135,$y+75,$line);imageline($im,$x+65,$y,$x+65,$y+75,$line);}}
    elseif($kind===1){for($x=240;$x<1000;$x+=350){imagesetthickness($im,7);imageline($im,$x,260,$x-90,650,$ink);imageline($im,$x,260,$x+90,650,$ink);for($y=350;$y<=600;$y+=100){imageline($im,$x-80,$y,$x+80,$y,$ink);imageline($im,$x-80,$y,$x+80,$y+70,$ink);}imageline($im,$x-120,320,$x+120,320,$ink);}for($y=290;$y<390;$y+=35)imagearc($im,580,$y-190,750,550,0,180,$blue);}
    else{imagefilledrectangle($im,410,320,790,650,$blue);for($x=445;$x<780;$x+=45)imageline($im,$x,350,$x,620,$line);for($x=460;$x<=740;$x+=140){imagefilledrectangle($im,$x,240,$x+25,320,$ink);imagefilledellipse($im,$x+12,250,60,20,$orange);}imagefilledrectangle($im,370,650,830,680,$ink);}
    imagefilledrectangle($im,0,0,1200,85,$ink);imagestring($im,5,35,32,'DEMO ONLY | ILLUSTRATION - NOT AN ACTUAL INSTALLATION',$white);imagestring($im,5,35,720,'AANSHU ENGINEERING | SAMPLE '.($kind+1).' / VIEW '.($variation+1),$ink);
    if(!imagejpeg($im,$directory.'/'.$name,88))throw new RuntimeException('Could not save demo image.');imagedestroy($im);return $name;
}
$staged=[];
try {
    if($mode==='seed') {
        if(!extension_loaded('gd'))throw new RuntimeException('PHP GD is required for the demo illustrations.');
        $db->beginTransaction();
        $projects=[['[DEMO] Residential rooftop solar gallery','Solar','Sample site — Odisha','Fictional demonstration of a rooftop solar project gallery. Illustrations show how multiple installation views can be displayed; no actual client, capacity, completion date or installation is claimed.'],['[DEMO] Electrical overhead line works','Electrical','Sample site — Odisha','Fictional demonstration of an electrical distribution project. The diagrams are placeholders for approved site photographs.'],['[DEMO] Transformer installation planning','Electrical','Sample site — Odisha','Draft example for an installation story. Replace it with genuine project details and approved photographs before publishing real work.']];
        foreach($projects as $i=>$p){$key=DEMO_PREFIX.'project:'.$i;if(demoQuery('SELECT id FROM projects WHERE demo_key=?',[$key])->fetch())continue;$photos=[];for($j=0;$j<3;$j++){$photo=demoImage($i,$j);$staged[]=$photo;$photos[]=$photo;demoQuery('INSERT INTO demo_assets (photo) VALUES (?)',[$photo]);}demoQuery('INSERT INTO projects (title,category,location,description,photo,published,demo_key) VALUES (?,?,?,?,?,?,?)',[...$p,$photos[0],$i<2?1:0,$key]);$id=(int)$db->lastInsertId();foreach($photos as $j=>$photo)demoQuery('INSERT INTO project_photos (project_id,photo,alt_text,sort_order) VALUES (?,?,?,?)',[$id,$photo,'DEMO illustration, not actual project photography — view '.($j+1),$j]);}
        $image=demoQuery('SELECT photo FROM projects WHERE demo_key=?',[DEMO_PREFIX.'project:0'])->fetchColumn() ?: null;
        $posts=[['[DEMO] What to share before a rooftop solar discussion','This is demonstration copy. For a real enquiry, share your location, roof access and electricity requirements with the team. Site suitability and the final scope need a project-specific assessment.'],['[DEMO] A look inside a project photo gallery','Sample company update illustrating how installation stories will look on the website. Replace the demo diagrams with approved photographs and accurate details.'],['[DEMO] Electrical works: planning the first conversation','Example update only. Describe the intended line or transformer work, location and available site information so the team can discuss the next steps.'],['[DEMO] Questions to ask before confirming a proposal','Demonstration educational post. Review scope, approvals, equipment, pricing and responsibilities with the provider before agreeing to a real project.'],['[DEMO] Draft: our next installation story','Draft sample. Add approved photos, factual project details and customer permission where applicable before publishing genuine work.']];
        foreach($posts as $i=>$p)demoQuery('INSERT IGNORE INTO posts (title,body,photo,published,demo_key) VALUES (?,?,?,?,?)',[$p[0],'[DEMO CONTENT — FICTIONAL SAMPLE] '.$p[1],$image,$i<4?1:0,DEMO_PREFIX.'post:'.$i]);
        $quotes=['The sample gallery makes it easy to understand what project photos could show.','The example callback form is straightforward to use.','This fictional review demonstrates a short customer testimonial.','This is sample feedback for checking the review layout on a phone.','A fictional rating to demonstrate a saved draft review.'];
        foreach($quotes as $i=>$quote)demoQuery('INSERT IGNORE INTO reviews (customer,location,quote,rating,published,demo_key) VALUES (?,?,?,?,?,?)',['[DEMO] Sample Customer '.($i+1),'Fictional location','[DEMO — NOT A GENUINE TESTIMONIAL] '.$quote,$i%2===0?5:4,$i<4?1:0,DEMO_PREFIX.'review:'.$i]);
        $services=['Rooftop solar','Electrical distribution','Transformer installation','Other'];
        for($i=0;$i<8;$i++)demoQuery('INSERT IGNORE INTO enquiries (name,phone,email,service,message,status,notification_status,demo_key) VALUES (?,?,?,?,?,?,?,?)',['[DEMO] Enquiry '.($i+1),'0000000000','sample'.($i+1).'@example.invalid',$services[$i%4],'[DEMO] Fictional enquiry for testing the admin inbox. No real person submitted this message. Do not call or email these placeholder details.',['new','contacted','closed'][$i%3],'demo_not_sent',DEMO_PREFIX.'enquiry:'.$i]);
        $db->commit();echo "Demo content seeded. Re-running adds only missing demo keys; existing records are preserved. No email, social post or notification was sent.\n";
    } elseif($mode==='purge') {
        $db->beginTransaction();foreach(['projects','posts','reviews','enquiries'] as $table)demoQuery("DELETE FROM $table WHERE demo_key LIKE ?",[DEMO_PREFIX.'%']);
        $db->commit();
        foreach(demoQuery('SELECT photo FROM demo_assets')->fetchAll(PDO::FETCH_COLUMN) as $photo){$used=demoQuery("SELECT (SELECT COUNT(*) FROM projects WHERE photo=?)+(SELECT COUNT(*) FROM project_photos WHERE photo=?)+(SELECT COUNT(*) FROM posts WHERE photo=?)+(SELECT COUNT(*) FROM social_jobs WHERE photo=?)+(SELECT COUNT(*) FROM seo_settings WHERE setting_key='social_photo' AND setting_value=?)",array_fill(0,5,$photo))->fetchColumn();if(!(int)$used){if(preg_match('/^[a-f0-9]{48}\.jpg$/D',$photo) && is_file($root.'/storage/photos/'.$photo))unlink($root.'/storage/photos/'.$photo);demoQuery('DELETE FROM demo_assets WHERE photo=?',[$photo]);}}
        echo "Tagged demo records removed. Real records and images still in use were preserved.\n";
    }
    foreach(['projects','posts','reviews','enquiries'] as $table)echo $table.': '.demoQuery("SELECT COUNT(*) FROM $table WHERE demo_key LIKE ?",[DEMO_PREFIX.'%'])->fetchColumn()." demo records\n";
} catch(Throwable $e){if($db->inTransaction())$db->rollBack();foreach($staged as $photo)if(is_file($root.'/storage/photos/'.$photo))unlink($root.'/storage/photos/'.$photo);fwrite(STDERR,'Demo command failed: '.$e->getMessage().PHP_EOL);exit(1);}
